async (page) => { await page.setViewportSize({width:1440,height:900}); const body = Buffer.from("",'base64').toString('utf8'); await page.unrouteAll(); const er=[]; page.on('pageerror',e=>er.push(e.message)); await page.route('https://tane.test/**', r => { const u=r.request().url(); if(u.endsWith('/')) return r.fulfill({status:200, contentType:'text/html; charset=utf-8', body}); return r.fulfill({status:404, body:''}); }); await page.goto('https://tane.test/'); await page.waitForTimeout(6000); const fr=[0.6, 0.64, 0.68]; for(let i=0;i<fr.length;i++){ await page.evaluate(f=>{window.scrollTo(0,(document.documentElement.scrollHeight-innerHeight)*f)},fr[i]); await page.waitForTimeout(400); await page.evaluate(()=>window.scrollBy(0,2)); await page.waitForTimeout(1800); await page.screenshot({path:'C:/Projeler/omer-skills/sosyal-onizleme/tane-premium/shots/s-'+i+'.jpg',type:'jpeg',quality:70}); } const ow=await page.evaluate(()=>document.documentElement.scrollWidth); return 'SONUC '+JSON.stringify({er,ow}); }